110: 	if err != nil || got == nil || got.Head != owner.Head || got.RequestedAt != owner.RequestedAt {
111: 		t.Fatalf("abandoned owner = %+v, %v; want original request metadata", got, err)
112: 	}
113: 	if gotAction := nextParallelReviewAction(false, true); gotAction != parallelReviewResume {
114: 		t.Fatalf("abandoned pending action = %q, want resume", gotAction)
115: 	}
116: 	if err := os.Remove(pendingPath); err != nil {
117: 		t.Fatal(err)
118: 	}
119: 	if err := clearParallelReviewOwner(ownerPath, pendingPath, owner.PID); err != nil {
120: 		t.Fatal(err)
121: 	}
122: 	if _, err := os.Stat(ownerPath); !os.IsNotExist(err) {
123: 		t.Fatalf("settled owner remains: %v", err)
124: 	}
