934: func (s *Service) startParallelGreenhouseReviews(ctx context.Context, db *store.DB, home string, project store.Project, change store.Task, targets []store.ReviewTarget) error {
935: 	requests, err := db.GreenhouseReviewRequests(ctx, project.ID)
936: 	if err != nil {
937: 		return err
938: 	}
939: 	for _, target := range targets {
940: 		exists := false
941: 		for _, request := range requests {
942: 			if request.TaskID == change.ID && request.Repository == target.Repository && request.RequestedHead == target.Commit && request.Outcome == "verdict" {
943: 				exists = true
944: 				break
945: 			}
946: 		}
947: 		roundDir := filepath.Join(home, "projects", project.Name, "tasks", taskIDString(change.Seq), "greenhouse")
948: 		pending := filepath.Join(roundDir, target.Repository+".pending.json")
949: 		_, pendingErr := os.Stat(pending)
950: 		hasPending := pendingErr == nil
951: 		if pendingErr != nil && !errors.Is(pendingErr, os.ErrNotExist) {
952: 			return pendingErr
953: 		}
954: 		lock, busy, err := acquireParallelReviewLock(parallelReviewLockPath(roundDir, target.Repository))
955: 		if err != nil {
956: 			return err
957: 		}
958: 		if busy {
959: 			continue
960: 		}
961: 		ownerPath := parallelReviewOwnerPath(roundDir, target.Repository)
962: 		owner, err := readParallelReviewOwner(ownerPath)
963: 		if err != nil {
964: 			_ = releaseParallelReviewLock(lock)
965: 			return err
966: 		}
967: 		action := nextParallelReviewAction(exists, hasPending)
968: 		if action == parallelReviewSkip {
969: 			if err := os.Remove(ownerPath); err != nil && !errors.Is(err, os.ErrNotExist) {
970: 				_ = releaseParallelReviewLock(lock)
971: 				return err
972: 			}
973: 			_ = releaseParallelReviewLock(lock)
974: 			continue
975: 		}
976: 		requestHead, requestStarted := parallelRequestMetadata(target.Commit, time.Now().UnixMilli(), hasPending, owner)
977: 		recordFailure := func(reason string) error {
978: 			if err := db.RecordGreenhouseReviewRequest(ctx, store.GreenhouseReviewRequest{ProjectID: project.ID, TaskID: change.ID, Repository: target.Repository, RequestedHead: requestHead, Provider: store.GreenhouseReviewProvider, RequestedAt: requestStarted, SettledAt: time.Now().UnixMilli(), Outcome: "failed"}); err != nil {
979: 				return err
980: 			}
981: 			_, err := db.CreateGreenhouseFailureNoticeOnce(ctx, project.ID, change.ID, target.Repository, requestHead, reason)
982: 			return err
983: 		}
984: 		binary, err := os.Executable()
985: 		if err != nil {
986: 			_ = releaseParallelReviewLock(lock)
987: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
988: 				return recordErr
989: 			}
990: 			continue
991: 		}
992: 		args := []string{"_greenhouse", "review", taskIDString(change.Seq), "--parallel-owner", ownerPath, "--parallel-lock-fd", "3"}
993: 		if project.IsWorkspace() {
994: 			args = append(args, "--repo", target.Repository)
995: 		}
996: 		command := exec.Command(binary, args...)
997: 		command.Dir = project.Root
