267: func greenhouseFindingsByHead(ctx context.Context, db *store.DB, projectID int64, requested map[comparisonHead]bool) (map[comparisonHead][]comparisonFinding, error) {
268: 	rows, err := db.QueryContext(ctx, `SELECT r.task_id,r.repo,r.requested_head,v.findings_path FROM greenhouse_review_requests r JOIN verdicts v ON v.id=r.verdict_id WHERE r.project_id=? AND r.outcome='verdict' ORDER BY r.task_id,r.repo,r.requested_head,r.id`, projectID)
269: 	if err != nil {
270: 		return nil, err
271: 	}
272: 	defer rows.Close()
273: 	findingsByHead := map[comparisonHead][]comparisonFinding{}
274: 	seen := map[comparisonHead]map[comparisonFinding]bool{}
275: 	for rows.Next() {
276: 		var key comparisonHead
277: 		var path string
278: 		if err := rows.Scan(&key.TaskID, &key.Repo, &key.Head, &path); err != nil {
279: 			return nil, err
280: 		}
281: 		if !requested[key] {
282: 			continue
283: 		}
284: 		data, err := os.ReadFile(path)
285: 		if err != nil {
286: 			return nil, err
287: 		}
288: 		var findings []comparisonFinding
289: 		if err := json.Unmarshal(data, &findings); err != nil {
290: 			return nil, err
291: 		}
292: 		if seen[key] == nil {
293: 			seen[key] = map[comparisonFinding]bool{}
294: 		}
295: 		for _, finding := range findings {
296: 			if seen[key][finding] {
297: 				continue
298: 			}
299: 			seen[key][finding] = true
300: 			findingsByHead[key] = append(findingsByHead[key], finding)
301: 		}
302: 	}
303: 	return findingsByHead, rows.Err()
304: }
