+		t.Fatal(err)
+	}
+	if err := clearParallelReviewOwner(ownerPath, pendingPath, owner.PID); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := os.Stat(ownerPath); !os.IsNotExist(err) {
+		t.Fatalf("settled owner remains: %v", err)
+	}
+}
