+			_ = command.Wait()
+			_ = os.Remove(ownerPath)
+			_ = releaseParallelReviewLock(lock)
+			if recordErr := recordFailure(err.Error()); recordErr != nil {
+				return recordErr
+			}
+			continue
+		}
+		_ = lock.Close()
+		go func() { _ = command.Wait() }()
+	}
+	return nil
+}
