917: // new head that is still skipped reaches the Lead again.
918: func recordAutoStartReviewerReadiness(ctx context.Context, db *store.DB, project store.Project, change store.Task, targets []store.ReviewTarget, failure *axi.Error) error {
919: 	heads := make([]string, len(targets))
920: 	for i, target := range targets {
921: 		heads[i] = target.Repository + "@" + shortSHA(target.Commit)
922: 	}
923: 	head := strings.Join(heads, ", ")
924: 	var found bool
925: 	if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM notices WHERE project_id=? AND task_id=? AND kind='review_auto_start_skipped' AND json_valid(data_json) AND json_extract(data_json,'$.head')=?)`, project.ID, change.ID, head).Scan(&found); err != nil || found {
926: 		return err
927: 	}
928: 	summary := fmt.Sprintf("%s: Review auto-start skipped at %s because no eligible reviewer is available: %s. Configure a reviewer Profile, then run `posse review start %s --profile <profile>`.", change.Title, head, failure.Message, taskIDString(change.Seq))
929: 	data := marshalJSON(map[string]any{"head": head, "reason_code": failure.Code, "reason": failure.Message, "help": failure.Help})
930: 	_, err := db.CreateNotice(ctx, store.Notice{ProjectID: project.ID, TaskID: change.ID, Kind: "review_auto_start_skipped", Summary: summary, DataJSON: data})
931: 	return err
932: }
